func asSlice(v interface{}) ([]interface{}, bool) {
    switch s := v.(type) {
    case []interface{}:
        return s, true
    case nil:
        return nil, false
    }
    rv := reflect.ValueOf(v)
    if rv.Kind() != reflect.Slice && rv.Kind() != reflect.Array {
        return nil, false
    }
    out := make([]interface{}, rv.Len())
    for i := 0; i < rv.Len(); i++ {
        out[i] = rv.Index(i).Interface()
    }
    return out, true
}
```

