func indexInto(v interface{}, i int) (interface{}, bool) {
    if i < 0 { return nil, false }
    switch s := v.(type) {
    case []interface{}:
        if i < len(s) { return s[i], true }
        return nil, false
    }
    rv := reflect.ValueOf(v)
    if rv.Kind() == reflect.Slice || rv.Kind() == reflect.Array {
        if i < rv.Len() { return rv.Index(i).Interface(), true }
    }
    return nil, false
}
```

