	sub := m.Sub("user")
	if sub == nil {
		t.Fatal("Sub(user) returned nil")
	}
	sub.Set("age", 36)
	if got, _ := m.GetInt("user.age"); got != 36 {
		t.Fatalf("Sub did not alias the parent map: age = %d", got)
